#include <Arduino.h>

// ========== MOTOR SETTINGS ==========

const float STEP_ANGLE_DEG = 1.8f;
const uint16_t STEPS_PER_REV =
    (uint16_t)(360.0f / STEP_ANGLE_DEG + 0.5f);

const uint8_t MOTOR_PINS[4] = {8, 9, 10, 11};
const uint8_t POT_PIN = A0;
const uint8_t BUTTON_PIN = 2;
const uint8_t DEBUG_PIN = 13;

const uint8_t SEQ_LEN = 4;
const uint8_t NUM_PINS = 4;

// Bipolar full-step sequence
const uint8_t STEP_SEQ[SEQ_LEN][NUM_PINS] = {
  {HIGH, LOW,  HIGH, LOW },
  {LOW,  HIGH, HIGH, LOW },
  {LOW,  HIGH, LOW,  HIGH},
  {HIGH, LOW,  LOW,  HIGH}
};

// ========== TIMING ==========

const uint16_t MIN_DELAY_MS = 2;
const uint16_t MAX_DELAY_MS = 20;

const uint16_t RAMP_STEPS = 40;

const unsigned long PAUSE_MS = 1000;
const unsigned long DEBOUNCE_MS = 50;

const int ADC_MAX = 1023;

// ========== MOTOR STATE ==========

enum MotionState {
  RUN_CW,
  WAIT_AFTER_CW,
  RUN_CCW
};

MotionState state = RUN_CW;

uint8_t stepIndex = 0;
uint16_t stepsDone = 0;

// Button toggles the direction
bool manualReverse = false;

// Timing
unsigned long lastStepMs = 0;
unsigned long pauseStartMs = 0;

// Potentiometer filter
int filteredPot = 0;

// ========== BUTTON STATE ==========

bool lastReading = HIGH;
bool stableReading = HIGH;
unsigned long lastChangeMs = 0;

// ========== APPLY STEP ==========

void applyStep(uint8_t index) {
  for (uint8_t i = 0; i < NUM_PINS; i++) {
    digitalWrite(MOTOR_PINS[i], STEP_SEQ[index][i]);
  }
}

// ========== POTENTIOMETER ==========

uint16_t getTargetDelay() {

  int rawValue = analogRead(POT_PIN);

  // Smooth analog readings
  filteredPot =
      (filteredPot * 7 + rawValue) / 8;

  // Higher pot reading = faster motor
  return (uint16_t)map(
      filteredPot,
      0,
      ADC_MAX,
      MAX_DELAY_MS,
      MIN_DELAY_MS
  );
}

// ========== SOFT START / SOFT STOP ==========

uint16_t getStepDelay() {
  return 20;
}

// ========== DEBOUNCED BUTTON ==========

void checkButton(unsigned long now) {

  bool reading = digitalRead(BUTTON_PIN);

  if (reading != lastReading) {
    lastChangeMs = now;
  }

  lastReading = reading;

  if ((now - lastChangeMs) >= DEBOUNCE_MS) {

    if (reading != stableReading) {

      stableReading = reading;

      if (stableReading == LOW) {

        // Reverse once per button press
        manualReverse = !manualReverse;

        // Begin a new full revolution
        // in the reversed direction
        if (state != WAIT_AFTER_CW) {
          stepsDone = 0;
          lastStepMs = now - MAX_DELAY_MS;
        }
      }
    }
  }
}

// ========== MOTOR DIRECTION ==========

int getDirection() {

  // Automatic direction
  int dir = (state == RUN_CCW) ? -1 : 1;

  // Manual button reversal
  if (manualReverse) {
    dir = -dir;
  }

  return dir;
}

// ========== ONE STEP ==========

void executeStep(int dir) {

  if (dir > 0) {
    stepIndex = (stepIndex + 1) % SEQ_LEN;
  } else {
    stepIndex =
        (stepIndex + SEQ_LEN - 1) % SEQ_LEN;
  }

  applyStep(stepIndex);

  // D13 indicates commanded direction
  // LOW = forward, HIGH = reverse
  digitalWrite(DEBUG_PIN,
               dir < 0 ? HIGH : LOW);
}

// ========== SETUP ==========

void setup() {

  for (uint8_t i = 0; i < NUM_PINS; i++) {
    pinMode(MOTOR_PINS[i], OUTPUT);
    digitalWrite(MOTOR_PINS[i], LOW);
  }

  pinMode(POT_PIN, INPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);

  pinMode(DEBUG_PIN, OUTPUT);
  digitalWrite(DEBUG_PIN, LOW);

  lastReading = digitalRead(BUTTON_PIN);
  stableReading = lastReading;

  filteredPot = analogRead(POT_PIN);

  applyStep(stepIndex);

  lastStepMs = millis() - MAX_DELAY_MS;
}

// ========== MAIN LOOP ==========

void loop() {

  unsigned long now = millis();

  // Always monitor button
  checkButton(now);

  // ----- One-second pause -----
  if (state == WAIT_AFTER_CW) {

    if (now - pauseStartMs >= PAUSE_MS) {

      state = RUN_CCW;
      stepsDone = 0;

      lastStepMs = now - MAX_DELAY_MS;
    }

    return;
  }

  // ----- Speed control and ramp -----
  uint16_t interval = getStepDelay();

  if (now - lastStepMs < interval) {
    return;
  }

  lastStepMs = now;

  // ----- Execute step -----
  int direction = getDirection();

  executeStep(direction);

  stepsDone++;

  // ----- Finished one revolution -----
  if (stepsDone >= STEPS_PER_REV) {

    stepsDone = 0;

    if (state == RUN_CW) {

      // CW -> 1-second pause
      state = WAIT_AFTER_CW;
      pauseStartMs = now;

    } else if (state == RUN_CCW) {

      // CCW -> repeat CW automatically
      state = RUN_CW;
    }
  }
}
